<style>
.checkout-page{padding-bottom:118px}.checkout-shell{display:grid;gap:14px}.checkout-steps{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.checkout-step{display:flex;align-items:center;justify-content:center;gap:6px;padding:9px 6px;border:1px solid var(--line);border-radius:13px;background:var(--surface);color:var(--muted);font-size:.7rem;font-weight:900}.checkout-step.active{color:var(--primary);border-color:color-mix(in srgb,var(--primary) 24%,var(--line));background:color-mix(in srgb,var(--primary) 5%,var(--surface))}.checkout-card{background:var(--surface);border:1px solid var(--line);border-radius:22px;padding:16px;box-shadow:0 10px 30px color-mix(in srgb,var(--text) 5%,transparent)}.checkout-section-title{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin:0 0 13px}.checkout-section-title h3{margin:0;font-size:1rem}.checkout-section-title small{display:block;color:var(--muted);font-size:.72rem;margin-top:3px;line-height:1.5}.eta-banner{display:flex;align-items:center;gap:10px;background:color-mix(in srgb,var(--primary) 8%,var(--surface));color:var(--primary);border:1px solid color-mix(in srgb,var(--primary) 18%,transparent);border-radius:16px;padding:12px 14px;font-weight:800;font-size:.82rem}.eta-banner i{font-size:1rem}.order-summary{background:var(--surface);border:1px solid var(--line);border-radius:22px;padding:14px}.cart-row{display:grid;grid-template-columns:56px minmax(0,1fr) auto;gap:10px;align-items:center;padding:10px 0;border-bottom:1px solid var(--line)}.cart-row:last-child{border-bottom:0}.cart-thumb{width:56px;height:56px;border-radius:15px;overflow:hidden;background:var(--bg)}.cart-thumb img{width:100%;height:100%;object-fit:cover}.row-copy strong{display:block;font-size:.84rem}.row-copy small{display:block;color:var(--muted);font-size:.72rem;margin-top:3px}.cart-total{display:flex;align-items:center;justify-content:space-between;padding-top:13px;margin-top:4px;border-top:1px solid var(--line);font-size:1rem;font-weight:900}.checkout-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.checkout-grid label,.field-label{display:block;font-size:.78rem;font-weight:800}.checkout-grid input,.checkout-grid select,.checkout-grid textarea,#paymentAccountSelect,#paymentReferenceInput{width:100%;margin-top:6px;border:1px solid var(--line);border-radius:14px;background:var(--surface);color:var(--text);min-height:49px;padding:10px 12px;outline:none}.checkout-grid textarea{min-height:92px;resize:vertical}.checkout-grid input:focus,.checkout-grid select:focus,.checkout-grid textarea:focus,#paymentAccountSelect:focus,#paymentReferenceInput:focus{border-color:var(--primary);box-shadow:0 0 0 3px color-mix(in srgb,var(--primary) 10%,transparent)}.checkout-grid .full{grid-column:1/-1}.table-legend{margin-top:8px}.payment-methods{display:grid;gap:9px}.payment-card{width:100%;display:grid;grid-template-columns:24px 44px minmax(0,1fr);align-items:center;gap:11px;text-align:right;border:1.5px solid var(--line);border-radius:17px;background:var(--surface);padding:11px 12px;color:var(--text);transition:.18s;cursor:pointer}.payment-card.active{border-color:var(--primary);background:color-mix(in srgb,var(--primary) 6%,var(--surface));box-shadow:0 0 0 2px color-mix(in srgb,var(--primary) 10%,transparent)}.payment-card .radio{width:20px;height:20px;border:2px solid var(--line);border-radius:50%;position:relative}.payment-card.active .radio{border-color:var(--primary)}.payment-card.active .radio:after{content:"";position:absolute;inset:4px;border-radius:50%;background:var(--primary)}.p-icon{width:44px;height:44px;border-radius:12px;background:color-mix(in srgb,var(--primary) 7%,var(--surface));display:grid;place-items:center;color:var(--primary)}.p-icon img{width:100%;height:100%;object-fit:contain;border-radius:10px}.p-copy strong{display:block;font-size:.84rem}.p-copy small{display:block;color:var(--muted);font-size:.68rem;margin-top:2px}.pay-account-card{margin-top:10px;padding:14px;border:1px solid var(--line);border-radius:15px;background:color-mix(in srgb,var(--bg) 55%,var(--surface))}.pay-account-card strong{display:block;margin-bottom:7px}.pay-account-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.pay-account-item{padding:9px;border-radius:10px;background:var(--surface)}.pay-account-item small{display:block;color:var(--muted);font-size:.68rem}.pay-account-item b{display:block;margin-top:2px;font-size:.8rem;overflow-wrap:anywhere}.pay-instructions{margin-top:9px;font-size:.77rem;color:var(--muted);line-height:1.7}.payment-extra{margin-top:12px}.proof-ai{display:flex;gap:10px;align-items:flex-start;margin-top:10px;padding:12px;border-radius:14px;background:color-mix(in srgb,var(--primary) 6%,var(--surface));border:1px solid color-mix(in srgb,var(--primary) 15%,var(--line));font-size:.74rem;line-height:1.65;color:var(--muted)}.proof-ai i{color:var(--primary);margin-top:3px}.proof-ai b{display:block;color:var(--text);font-size:.78rem}.proof-ai .ai-ready{display:none;margin-top:6px;color:var(--primary);font-weight:900}.proof-ai .ai-ready.show{display:block}.upload-preview{margin-top:9px;padding:10px;border-radius:13px;background:var(--surface);border:1px solid var(--line);display:flex;align-items:center;gap:10px}.upload-preview img{width:64px;height:64px;object-fit:cover;border-radius:10px}.submit-wrap{position:sticky;bottom:calc(70px + env(safe-area-inset-bottom,0px));z-index:15;padding-top:12px;background:linear-gradient(180deg,transparent,var(--bg) 32%)}.submit-order{width:100%;border:0;border-radius:16px;background:var(--primary);color:#fff;padding:15px;font-weight:900;font-size:.94rem;box-shadow:0 12px 24px color-mix(in srgb,var(--primary) 24%,transparent);cursor:pointer}.submit-order:disabled{opacity:.65}.error{color:#b42318;font-size:.8rem;font-weight:700;margin:8px 0}.checkout-note{font-size:.72rem;color:var(--muted);line-height:1.6;margin-top:7px}.required-star{color:#d64545}@media(max-width:560px){.checkout-grid{grid-template-columns:1fr}.pay-account-grid{grid-template-columns:1fr}.checkout-card{padding:14px}.cart-row{grid-template-columns:50px minmax(0,1fr) auto}.cart-thumb{width:50px;height:50px}.checkout-step{font-size:.64rem;padding:8px 4px}}
