<script>
const CM=window.CustomerMenu,ORDER_URL=@json(route('customer-menu.orders.store',$location->code)),PAYMENT_URL=@json(route('customer-menu.payment-options',$location->code)),QUEUE_URL=@json(route('customer-menu.queue-status',$location->code)),CART_URL=@json(route('customer-menu.cart',$location->code)),TRACK_BASE=@json(route('customer-menu.show',$location->code)),REQUEST_TOKEN=@json($requestToken??''),CSRF=document.querySelector('meta[name="csrf-token"]').content;let methods=[];
function renderSummary(){const rows=CM.cartRows();if(!rows.length){location.href=CART_URL;return}document.getElementById('summaryItems').innerHTML=rows.map(x=>{const mods=(x.modifiers||[]).map(m=>`${m.name}${m.quantity>1?' ×'+m.quantity:''}`).join('، '),sub=[x.variant_name,mods].filter(Boolean).join(' — ');return `<div class="cart-row"><div class="cart-thumb">${x.image?`<img src="${CM.esc(x.image)}" alt="">`:''}</div><div class="row-copy"><strong>${CM.esc(x.name.split(' - ')[0])}</strong>${sub?`<span style="display:block;font-size:.7rem;color:var(--muted);margin-top:2px">${CM.esc(sub)}</span>`:''}<small>${x.quantity} × ${CM.money(x.price)}</small></div><div class="row-copy"><strong>${CM.money(x.price*x.quantity)}</strong></div></div>`}).join('');document.getElementById('summaryTotal').textContent=CM.money(CM.cartTotal())}
function serviceFields(){const v=document.getElementById('serviceType').value;document.getElementById('tableField').hidden=v!=='dine_in';document.getElementById('addressField').hidden=v!=='delivery'}
document.getElementById('tableGrid').addEventListener('click',e=>{const c=e.target.closest('.table-card');if(!c||c.disabled)return;document.querySelectorAll('.table-card').forEach(x=>x.classList.remove('selected'));c.classList.add('selected');document.getElementById('tableIdInput').value=c.dataset.tableId});
async function loadPayments(){try{const r=await fetch(PAYMENT_URL,{headers:{Accept:'application/json'},cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.message||'تعذر تحميل طرق الدفع');methods=d.payment_methods||d.methods||[];document.getElementById('paymentMethods').innerHTML=methods.length?methods.map(m=>`<button class="payment-card" type="button" data-pay="${m.id}"><span class="radio"></span><span class="p-icon">${m.logo?`<img src="${CM.esc(m.logo)}" alt="${CM.esc(m.name)}">`:`<i class="${paymentIcon(m.type)}"></i>`}</span><span class="p-copy"><strong>${CM.esc(m.name)}</strong><small>${paymentTypeLabel(m.type,m.requires_verification)}</small></span></button>`).join(''):'لا توجد طرق دفع مفعلة.'}catch(e){document.getElementById('paymentMethods').innerHTML=`<div class="error">${CM.esc(e.message)}</div>`}}
function paymentIcon(t){switch(String(t||'').toLowerCase()){case'cash':return'fa-solid fa-money-bill-wave';case'card_pos':return'fa-solid fa-credit-card';case'bank_transfer':return'fa-solid fa-building-columns';case'electronic_wallet':return'fa-solid fa-wallet';default:return'fa-solid fa-circle-dollar-to-slot'}}
function paymentTypeLabel(t,verify){if(verify)return'يتطلب مراجعة إثبات الدفع';switch(String(t||'').toLowerCase()){case'cash':return'الدفع نقدًا';case'card_pos':return'بطاقة عند نقطة البيع';case'bank_transfer':return'تحويل بنكي';case'electronic_wallet':return'محفظة إلكترونية';default:return'طريقة دفع'}}
function accountDetailHtml(a){if(!a)return'';const rows=[['مزود الخدمة',a.provider_name],['اسم صاحب الحساب',a.account_holder_name],['رقم الحساب',a.account_number],['IBAN',a.iban],['رقم الجوال/المحفظة',a.phone_number]].filter(x=>x[1]);return `<div class="pay-account-card"><strong>${CM.esc(a.name||a.provider_name||'بيانات التحويل')}</strong>${rows.length?`<div class="pay-account-grid">${rows.map(([k,v])=>`<div class="pay-account-item"><small>${CM.esc(k)}</small><b>${CM.esc(v)}</b></div>`).join('')}</div>`:''}${a.instructions?`<div class="pay-instructions">${CM.esc(a.instructions)}</div>`:''}</div>`}
function renderAccount(method){const accounts=method.accounts||[],holder=document.getElementById('paymentAccountDetails');document.getElementById('paymentAccountId').value='';if(!accounts.length){holder.innerHTML='';return}holder.innerHTML=`<label class="field-label" style="margin-top:12px">حساب التحويل<select id="paymentAccountSelect" required><option value="">اختر الحساب</option>${accounts.map(a=>`<option value="${a.id}">${CM.esc(a.name||a.provider_name||a.account_number||'حساب')}</option>`).join('')}</select></label><div id="selectedAccountDetails"></div>`}
function choosePayment(id){const m=methods.find(x=>String(x.id)===String(id));if(!m)return;document.getElementById('paymentMethodId').value=m.id;document.querySelectorAll('[data-pay]').forEach(b=>b.classList.toggle('active',String(b.dataset.pay)===String(id)));renderAccount(m);const pureCash=String(m.type||'').toLowerCase()==='cash'&&!m.requires_reference&&!m.requires_verification,refField=document.getElementById('paymentReferenceField'),ref=document.getElementById('paymentReferenceInput'),refStar=document.getElementById('referenceRequiredStar');refField.hidden=pureCash;ref.required=!pureCash&&!!m.requires_reference;refStar.hidden=!ref.required;if(pureCash)ref.value='';const proofField=document.getElementById('paymentProofField'),proof=document.getElementById('paymentProofInput'),proofStar=document.getElementById('proofRequiredStar');proofField.hidden=pureCash;proof.required=!pureCash&&!!m.requires_verification;proofStar.hidden=!proof.required;if(pureCash){proof.value='';document.getElementById('uploadPreview').hidden=true;document.getElementById('aiReady').classList.remove('show')}}
document.addEventListener('click',e=>{const p=e.target.closest('[data-pay]');if(p)choosePayment(p.dataset.pay)});
document.addEventListener('change',e=>{if(e.target.id==='paymentAccountSelect'){const method=methods.find(x=>String(x.id)===String(document.getElementById('paymentMethodId').value)),account=(method?.accounts||[]).find(x=>String(x.id)===String(e.target.value));document.getElementById('paymentAccountId').value=e.target.value;const target=document.getElementById('selectedAccountDetails');if(target)target.innerHTML=accountDetailHtml(account)}});
document.getElementById('paymentProofInput').addEventListener('change',e=>{const f=e.target.files[0],p=document.getElementById('uploadPreview');if(!f){p.hidden=true;document.getElementById('aiReady').classList.remove('show');return}p.hidden=false;p.innerHTML=`${f.type.startsWith('image/')?`<img src="${URL.createObjectURL(f)}" alt="إثبات الدفع">`:`<i class="fa-solid fa-file-pdf" style="font-size:1.6rem;color:var(--primary)"></i>`}<span><strong style="display:block">${CM.esc(f.name)}</strong><small style="color:var(--muted)">${Math.max(1,Math.round(f.size/1024))} KB</small></span>`;document.getElementById('aiReady').classList.add('show')});
document.getElementById('serviceType').addEventListener('change',serviceFields);
document.getElementById('checkoutForm').addEventListener('submit',async e=>{e.preventDefault();const rows=CM.cartRows();if(!rows.length)return;const err=document.getElementById('checkoutError'),btn=document.getElementById('checkoutSubmit');err.textContent='';const serviceType=document.getElementById('serviceType').value;if(serviceType==='dine_in'&&!document.getElementById('tableIdInput').value){err.textContent='اختر الطاولة قبل إرسال الطلب.';return}if(!document.getElementById('paymentMethodId').value){err.textContent='اختر طريقة الدفع.';return}const selectedMethod=methods.find(x=>String(x.id)===String(document.getElementById('paymentMethodId').value));if((selectedMethod?.accounts||[]).length&&!document.getElementById('paymentAccountId').value){err.textContent='اختر حساب التحويل.';return}btn.disabled=true;btn.textContent='جاري إرسال الطلب...';try{const fd=new FormData(e.currentTarget);fd.append('request_token',REQUEST_TOKEN);rows.forEach((row,i)=>{fd.append(`items[${i}][product_id]`,row.product_id);fd.append(`items[${i}][quantity]`,row.quantity);if(row.variant_id)fd.append(`items[${i}][product_variant_id]`,row.variant_id);(row.modifiers||[]).forEach((m,j)=>{fd.append(`items[${i}][modifiers][${j}][modifier_id]`,m.modifier_id);fd.append(`items[${i}][modifiers][${j}][quantity]`,m.quantity)})});const r=await fetch(ORDER_URL,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':CSRF},body:fd}),d=await r.json();if(!r.ok)throw new Error(d.message||Object.values(d.errors||{}).flat()[0]||'تعذر إرسال الطلب');CM.pushOrder({order_id:d.order_id||null,order_number:d.order_number,location:CM.LOCATION_CODE,url:d.track_url,created_at:d.created_at||new Date().toLocaleString('ar')});CM.clearCart();CM.toast('تم استلام طلبك بنجاح');setTimeout(()=>location.href=d.track_url||TRACK_BASE,650)}catch(ex){err.textContent=ex.message}finally{btn.disabled=false;btn.textContent='تأكيد وإرسال الطلب'}});
renderSummary();serviceFields();loadPayments();(async()=>{try{const r=await fetch(QUEUE_URL,{headers:{Accept:'application/json'},cache:'no-store'}),d=await r.json();if(!r.ok)return;const rows=CM.cartRows(),defaultPrep=Number(d.default_prep_minutes)||12,itemLoads=rows.map(row=>{const base=Number(row.prep_time_minutes)||defaultPrep,qty=Math.max(1,Number(row.quantity)||1);return Math.ceil(base+(Math.max(0,qty-1)*base*.35))}),kitchenLoad=Math.max(defaultPrep,...itemLoads),queueLoad=(Number(d.queue_count)||0)*(Number(d.queue_minutes_per_order)||0),mins=Math.max(1,Math.ceil(kitchenLoad+queueLoad));document.getElementById('etaText').textContent=`الوقت المتوقع لتجهيز طلبك: حوالي ${mins} دقيقة`;document.getElementById('etaBanner').hidden=false}catch(e){}})();
</script>
</body></html>
